import math

def run_experiment(inputs, dataset_rows):
    n0 = float(inputs["initial_population"])
    rate = float(inputs["growth_rate"])
    capacities = [float(k) for k in inputs["capacities"]]
    duration, steps = float(inputs["duration"]), int(inputs["steps"])
    if not (n0 > 0 and rate > 0 and 0 < duration <= 1000 and 1 <= steps <= 1000):
        raise ValueError("Invalid model parameters")
    if not capacities or len(capacities) > 8 or any(k <= n0 for k in capacities):
        raise ValueError("Each carrying capacity must exceed the initial population")
    series, metrics = [], {}
    rows = ["carrying_capacity,time,population"]
    for capacity in capacities:
        points = []
        for i in range(steps + 1):
            time = duration * i / steps
            population = capacity / (1 + (capacity/n0 - 1) * math.exp(-rate*time))
            if not (0 < population <= capacity):
                raise ValueError("Population bounds check failed")
            points.append({"x":time,"y":population})
            rows.append(f"{capacity},{time},{population}")
        if abs(points[0]["y"]-n0) > 1e-9:
            raise ValueError("Initial condition check failed")
        series.append({"name":f"K={capacity:g}","points":points})
        metrics[f"K={capacity:g}"] = {"final_population":points[-1]["y"],"initial_condition_checked":True}
    return {"kind":"simulation","metrics":metrics,"findings":[f"{name}: population at t={duration:g} is {value['final_population']:.5g}." for name,value in metrics.items()],"limitations":["Illustrative exact logistic model; no observed data were used."],"series":series,"x_axis_label":"Time (illustrative time units)","y_axis_label":"Population (individuals)","csv":"\n".join(rows)}
